package game

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"sort"
	"strconv"
)

// Combat styles registry: the port of
// game/content/combat/CombatStyleDefinitions.ts (50 lines) and the
// FightType registry half of game/content/combat/FightType.ts (203
// lines). The weapon-interface half of the same data lives in
// weapon_interface.go; both halves load from the one file.
//
// DATA DECISION (Phase 26, Worker B): the rows are imported
// VERBATIM from the upstream generated file — option (b) of the
// brief — not transcribed as Go literals. Evidence:
//   - The file is 32,838 bytes: 161 fight types + 53 weapon
//     interfaces (data/definitions/item-combat-styles.json).
//     Transcribing 214 rows x 6-8 fields (~1,500 values) by hand
//     is pure error surface; the verbatim file is the data.
//   - Precedent: Phase 8 imported music-areas.json verbatim
//     into the same directory (data/definitions/music-areas.json
//     is byte-identical to the upstream file, same SHA-256);
//     music.LoadAreas reads it from disk at boot, and this
//     loader follows that shape (read at boot, never embedded).
//   - The upstream file is generated by
//     server/scripts/dump-item-combat-styles.ts from cache
//     dbtable 78 (cache osrs-242_2026-11-03); the cache-derived
//     fields (childId, style, attackType) refresh from the
//     cache on re-dump, while animation, sound, rapid and
//     interface metadata are server-owned and preserved.
//     Refresh is therefore: re-copy the upstream file verbatim
//     and update CombatStylesSHA256 below. NEVER hand-edit the
//     copied file: it is generated upstream, and a hand edit
//     would be silently overwritten by the next refresh (the
//     same rule the upstream AGENTS.md states for generated
//     JSON).
// Verification: LoadCombatStyles rejects bytes whose SHA-256
// differs from CombatStylesSHA256, so a stale, truncated or
// tampered file loads as nothing (the caller falls back to
// the UNARMED-only registry) instead of silently wrong
// styles. Unit tests use hand-built fixture JSON only and
// never read the shipped file.

// CombatStyleVarp is COMBAT_STYLE_PARENT_ID (FightType.ts): every
// style reports against varp 43 (com_mode).
const CombatStyleVarp = 43

// WeaponCategoryVarbit is WEAPON_CATEGORY_VARBIT
// (WeaponInterfaceManager.ts): the varbit carrying the equipped
// weapon's category.
const WeaponCategoryVarbit = 357

// AutoRetaliateVarp is varp 172 (%option_nodef): inverted, 0
// enables auto-retaliate (WeaponInterfaceManager.ts).
const AutoRetaliateVarp = 172

// CombatInterfaceGroup is the combat tab group (593):
// NetworkBuilder.ts COMBAT_INTERFACE, and the group
// WeaponInterfaceManager.assign mounts on tab 0.
const CombatInterfaceGroup = 593

// CombatStyleByCategoryAttribute is
// COMBAT_STYLE_BY_CATEGORY_ATTRIBUTE (FightType.ts): the
// per-category remembered style slot. It is already a seeded
// persistent key with default "{}" (persist core seed, from
// PlayerSave.ts:793-798), so values round-trip through saves
// with no registration work here.
const CombatStyleByCategoryAttribute = "combat:style-by-category"

// CombatStylesSHA256 is the SHA-256 of the verbatim upstream
// data/definitions/item-combat-styles.json at commit bfd81e3
// (cache osrs-242_2026-11-03). Update it, and only it, when the
// file is refreshed from upstream.
const CombatStylesSHA256 = "d8856054f42a78d975e1ff826162a18147d5e006b2b88dd2dd8cef28e5bcd384"

// CombatStylesFile is the file name the loader reads from the
// definitions directory (data/definitions/), following the
// music-areas.json precedent.
const CombatStylesFile = "item-combat-styles.json"

// WeaponInterface is one row of the weaponInterfaces table
// (WeaponInterfaces.ts): a weapon category's combat tab — its
// interface ids, attack speed, category, special bar, and the
// fight types it offers.
type WeaponInterface struct {
	// Name is the registry key (e.g. "STAFF", "WHIP").
	Name string
	// InterfaceID is the combat-tab interface id.
	InterfaceID int
	// NameLineID is the component the weapon name is written
	// to (sendString(name, nameLineId)).
	NameLineID int
	// Speed is the attack speed in ticks (WeaponInterfaces.ts
	// getSpeed). It is data only here: the live base attack
	// speed still comes from the item definition's attack
	// speed (WeaponInfoSource), as before.
	Speed int
	// Category is the weapon category (varbit 357 value).
	Category int
	// SpecialBar / SpecialMeter are the special-attack bar
	// component ids, or -1 when the interface has none.
	SpecialBar   int
	SpecialMeter int
	// FightTypes are the styles this weapon offers, in file
	// order.
	FightTypes []*FightType
}

// FightTypeForChild returns the offered style with the given
// child id (varp 43 slot), or nil.
func (w *WeaponInterface) FightTypeForChild(childID int) *FightType {
	if w == nil {
		return nil
	}
	for _, ft := range w.FightTypes {
		if ft != nil && ft.ChildID == childID {
			return ft
		}
	}
	return nil
}

// LowestFightType returns the offered style with the smallest
// child id (WeaponInterfaceManager.assign's reduce), or nil
// when the interface offers nothing.
func (w *WeaponInterface) LowestFightType() *FightType {
	if w == nil {
		return nil
	}
	var lowest *FightType
	for _, ft := range w.FightTypes {
		if ft == nil {
			continue
		}
		if lowest == nil || ft.ChildID < lowest.ChildID {
			lowest = ft
		}
	}
	return lowest
}

// HasFightType reports whether ft is one of the offered styles
// (pointer identity, as TS checks `type === currentFightType`
// in WeaponInterfaceManager.assign).
func (w *WeaponInterface) HasFightType(ft *FightType) bool {
	if w == nil || ft == nil {
		return false
	}
	for _, offered := range w.FightTypes {
		if offered == ft {
			return true
		}
	}
	return false
}

// CombatStyleRegistry is the loaded item-combat-styles.json:
// every fight type and weapon interface, keyed by JSON key.
// It is read-only after loading (InstallCombatStyles installs
// it once at boot); concurrent reads are safe.
type CombatStyleRegistry struct {
	fightTypes map[string]*FightType
	interfaces map[string]*WeaponInterface
}

// FightType returns the fight type with the given JSON key, or
// nil.
func (r *CombatStyleRegistry) FightType(name string) *FightType {
	if r == nil {
		return nil
	}
	return r.fightTypes[name]
}

// WeaponInterface returns the weapon interface with the given
// JSON key, or nil.
func (r *CombatStyleRegistry) WeaponInterface(name string) *WeaponInterface {
	if r == nil {
		return nil
	}
	return r.interfaces[name]
}

// FightTypeCount returns the number of loaded fight types.
func (r *CombatStyleRegistry) FightTypeCount() int {
	if r == nil {
		return 0
	}
	return len(r.fightTypes)
}

// WeaponInterfaceCount returns the number of loaded weapon
// interfaces.
func (r *CombatStyleRegistry) WeaponInterfaceCount() int {
	if r == nil {
		return 0
	}
	return len(r.interfaces)
}

// FightTypes returns every loaded fight type, sorted by key
// (the JSON object order is not preserved by decoding).
func (r *CombatStyleRegistry) FightTypes() []*FightType {
	if r == nil {
		return nil
	}
	keys := make([]string, 0, len(r.fightTypes))
	for k := range r.fightTypes {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	out := make([]*FightType, 0, len(keys))
	for _, k := range keys {
		out = append(out, r.fightTypes[k])
	}
	return out
}

// WeaponInterfaces returns every loaded weapon interface,
// sorted by key.
func (r *CombatStyleRegistry) WeaponInterfaces() []*WeaponInterface {
	if r == nil {
		return nil
	}
	keys := make([]string, 0, len(r.interfaces))
	for k := range r.interfaces {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	out := make([]*WeaponInterface, 0, len(keys))
	for _, k := range keys {
		out = append(out, r.interfaces[k])
	}
	return out
}

// InterfaceForItem resolves an equipped item id to its weapon
// interface through the item-definition weapon-interface name
// (ItemDefinition.getWeaponInterface, ItemDefinition.ts:329-331;
// Go: WeaponInfoSource.WeaponInterfaceName, carried from
// item-gameplay.json). An id with no name, an unknown name, or
// a nil source reads nil: the caller falls back to UNARMED,
// as WeaponInterfaceManager.assign does when the equipped
// item has no definition interface.
func (r *CombatStyleRegistry) InterfaceForItem(id int, src WeaponInfoSource) *WeaponInterface {
	if r == nil || id <= 0 || src == nil {
		return nil
	}
	name := src.WeaponInterfaceName(id)
	if name == "" {
		return nil
	}
	return r.interfaces[name]
}

// ResolveFightType is FightType.resolve (FightType.ts): the
// stored fight type when it is one of the available styles,
// else the first available style whose animation, parent,
// child and bonus-type fields all match the stored one's
// (a field is ignored when the stored value carries no such
// field — in Go, a nil stored type never resolves). A nil
// registry resolves nothing.
func (r *CombatStyleRegistry) ResolveFightType(ft *FightType, available []*FightType) *FightType {
	if r == nil || ft == nil {
		return nil
	}
	for _, offered := range available {
		if offered == ft {
			return offered
		}
	}
	for _, offered := range available {
		if offered != nil &&
			offered.Animation == ft.Animation &&
			offered.ParentID == ft.ParentID &&
			offered.ChildID == ft.ChildID &&
			offered.BonusType == ft.BonusType {
			return offered
		}
	}
	return nil
}

// combatStylesFile is the JSON shape of
// item-combat-styles.json (CombatStyleDefinitions.ts):
// fightTypes and weaponInterfaces keyed by name, plus the
// $comment/cache header fields, which are read and ignored.
type combatStylesFile struct {
	FightTypes map[string]combatFightTypeJSON `json:"fightTypes"`
	Interfaces map[string]combatWeaponJSON    `json:"weaponInterfaces"`
}

type combatFightTypeJSON struct {
	Animation    int    `json:"animation"`
	NPCAnimation *int   `json:"npcAnimation"`
	ChildID      int    `json:"childId"`
	AttackType   string `json:"attackType"`
	Style        string `json:"style"`
	Sound        string `json:"sound"`
	Rapid        bool   `json:"rapid"`
}

type combatWeaponJSON struct {
	InterfaceID  int      `json:"interfaceId"`
	NameLineID   int      `json:"nameLineId"`
	Speed        int      `json:"speed"`
	Category     int      `json:"category"`
	SpecialBar   *int     `json:"specialBar"`
	SpecialMeter *int     `json:"specialMeter"`
	FightTypes   []string `json:"fightTypes"`
}

// LoadCombatStyles parses and verifies item-combat-styles.json
// bytes: the SHA-256 must match CombatStylesSHA256 (see the
// file header), and every interface's fight-type names must
// resolve — TS throws on an unknown fight type for an
// interface (WeaponInterfaces.ts static block), and the Go
// loader errors the same way instead of building a registry
// with dangling styles. Attack-type and style names map with
// the TS fallbacks (FightType.ts static block): an unknown
// attack type reads CRUSH, an unknown style reads ACCURATE,
// an unknown sound reads WEAPON.
func LoadCombatStyles(data []byte) (*CombatStyleRegistry, error) {
	sum := sha256.Sum256(data)
	if hex.EncodeToString(sum[:]) != CombatStylesSHA256 {
		return nil, fmt.Errorf("combat styles: SHA-256 mismatch (want %s)", CombatStylesSHA256)
	}
	return parseCombatStyles(data)
}

// parseCombatStyles parses item-combat-styles.json bytes without
// the SHA check. LoadCombatStyles is the production entry point;
// tests use this directly with hand-built fixture JSON (the
// shipped file's SHA cannot match a fixture).
func parseCombatStyles(data []byte) (*CombatStyleRegistry, error) {
	var file combatStylesFile
	if err := json.Unmarshal(data, &file); err != nil {
		return nil, fmt.Errorf("combat styles: parsing item-combat-styles.json: %w", err)
	}
	return buildCombatStyleRegistry(file)
}

func buildCombatStyleRegistry(file combatStylesFile) (*CombatStyleRegistry, error) {
	reg := &CombatStyleRegistry{
		fightTypes: make(map[string]*FightType, len(file.FightTypes)),
		interfaces: make(map[string]*WeaponInterface, len(file.Interfaces)),
	}
	for key, def := range file.FightTypes {
		npcAnimation := -1
		if def.NPCAnimation != nil {
			npcAnimation = *def.NPCAnimation
		}
		sound, ok := ResolveKnownSound(def.Sound)
		if !ok {
			sound, _ = ResolveKnownSound("WEAPON")
		}
		reg.fightTypes[key] = &FightType{
			Name:         key,
			Animation:    def.Animation,
			NPCAnimation: npcAnimation,
			ChildID:      def.ChildID,
			ParentID:     CombatStyleVarp,
			BonusType:    combatAttackBonus(def.AttackType),
			Style:        combatFightStyle(def.Style),
			Sound:        sound,
			Rapid:        def.Rapid,
		}
	}
	for key, def := range file.Interfaces {
		iface := &WeaponInterface{
			Name:         key,
			InterfaceID:  def.InterfaceID,
			NameLineID:   def.NameLineID,
			Speed:        def.Speed,
			Category:     def.Category,
			SpecialBar:   -1,
			SpecialMeter: -1,
		}
		if def.SpecialBar != nil {
			iface.SpecialBar = *def.SpecialBar
		}
		if def.SpecialMeter != nil {
			iface.SpecialMeter = *def.SpecialMeter
		}
		for _, name := range def.FightTypes {
			ft := reg.fightTypes[name]
			if ft == nil {
				return nil, fmt.Errorf("combat styles: unknown fight type %q for weapon interface %s", name, key)
			}
			iface.FightTypes = append(iface.FightTypes, ft)
		}
		reg.interfaces[key] = iface
	}
	return reg, nil
}

// combatAttackBonus maps a JSON attack-type name to its bonus
// index (FightType.ts ATTACK_TYPE_BY_NAME): STAB 0, SLASH 1,
// CRUSH 2, MAGIC 3, RANGE 4; anything else reads CRUSH.
func combatAttackBonus(attackType string) int {
	switch attackType {
	case "STAB":
		return BonusAttackStab
	case "SLASH":
		return BonusAttackSlash
	case "CRUSH":
		return BonusAttackCrush
	case "MAGIC":
		return BonusAttackMagic
	case "RANGE":
		return BonusAttackRange
	default:
		return BonusAttackCrush
	}
}

// combatFightStyle maps a JSON style name to its FightStyle
// (FightType.ts STYLE_BY_NAME); anything else reads ACCURATE.
func combatFightStyle(style string) FightStyle {
	switch style {
	case "ACCURATE":
		return FightStyleAccurate
	case "AGGRESSIVE":
		return FightStyleAggressive
	case "DEFENSIVE":
		return FightStyleDefensive
	case "CONTROLLED":
		return FightStyleControlled
	default:
		return FightStyleAccurate
	}
}

// UnarmedFallbackRegistry is the UNARMED-only registry used
// when no combat-styles file is installed (NoCache mode, a
// failed load, unit tests that install nothing): the three
// UNARMED rows transcribed verbatim from
// item-combat-styles.json (UNARMED_PUNCH: Punch, 422, child 0,
// CRUSH, ACCURATE, WEAPON_UNARMED_PUNCH; UNARMED_KICK: Kick,
// 423, child 1, CRUSH, AGGRESSIVE, WEAPON_UNARMED_KICK;
// UNARMED_BLOCK: Block, 422, child 3, CRUSH, DEFENSIVE,
// WEAPON_UNARMED_PUNCH; UNARMED interface 5855, name line
// 5857, speed 4, category 0, no special bar). Every weapon
// resolves to UNARMED through it, exactly as an empty
// item-combat-styles.json would.
func UnarmedFallbackRegistry() *CombatStyleRegistry {
	kickSound, _ := ResolveKnownSound("WEAPON_UNARMED_KICK")
	punchSound, _ := ResolveKnownSound("WEAPON_UNARMED_PUNCH")
	punch := &FightType{
		Name: "UNARMED_PUNCH", Animation: 422, NPCAnimation: -1,
		ChildID: 0, ParentID: CombatStyleVarp, BonusType: BonusAttackCrush,
		Style: FightStyleAccurate, Sound: punchSound,
	}
	kick := &FightType{
		Name: "UNARMED_KICK", Animation: 423, NPCAnimation: -1,
		ChildID: 1, ParentID: CombatStyleVarp, BonusType: BonusAttackCrush,
		Style: FightStyleAggressive, Sound: kickSound,
	}
	block := &FightType{
		Name: "UNARMED_BLOCK", Animation: 422, NPCAnimation: -1,
		ChildID: 3, ParentID: CombatStyleVarp, BonusType: BonusAttackCrush,
		Style: FightStyleDefensive, Sound: punchSound,
	}
	return &CombatStyleRegistry{
		fightTypes: map[string]*FightType{
			"UNARMED_PUNCH": punch,
			"UNARMED_KICK":  kick,
			"UNARMED_BLOCK": block,
		},
		interfaces: map[string]*WeaponInterface{
			"UNARMED": {
				Name: "UNARMED", InterfaceID: 5855, NameLineID: 5857,
				Speed: 4, Category: 0, SpecialBar: -1, SpecialMeter: -1,
				FightTypes: []*FightType{punch, kick, block},
			},
		},
	}
}

// installedCombatStyles is the boot-installed registry
// (InstallCombatStyles, cmd/server/combatstylewiring.go). It
// follows the RegisterCombatSpecial precedent: read-only after
// installation, so concurrent reads need no guard. A nil
// install reads as the UNARMED fallback.
var installedCombatStyles *CombatStyleRegistry

// InstallCombatStyles installs the loaded registry, returning
// the previously installed one (nil when none was installed)
// so tests can restore it. A nil registry installs the
// UNARMED fallback.
func InstallCombatStyles(reg *CombatStyleRegistry) *CombatStyleRegistry {
	previous := installedCombatStyles
	if reg == nil {
		reg = UnarmedFallbackRegistry()
	}
	installedCombatStyles = reg
	return previous
}

// CombatStyles returns the installed registry, or the UNARMED
// fallback when nothing was installed.
func CombatStyles() *CombatStyleRegistry {
	if installedCombatStyles == nil {
		return UnarmedFallbackRegistry()
	}
	return installedCombatStyles
}

// RememberCombatStyle stores the chosen style slot for a
// weapon category (WeaponInterfaceManager.rememberStyle): the
// attribute holds a fresh map[string]int on every write (TS
// spreads {...styles, [category]: childId}), keyed by the
// decimal category — map keys must be strings for the save's
// cloneAttribute JSON-compatibility rule (persist/attributes.go:
// a map[int]... has no JSON object form). The attribute is a
// seeded persistent key (default "{}"), so the memory survives
// logout (FightType.ts header comment).
func RememberCombatStyle(p *Player, category, childID int) {
	if p == nil {
		return
	}
	styles := readCombatStyleMemory(p)
	remembered := make(map[string]int, len(styles)+1)
	for k, v := range styles {
		remembered[k] = v
	}
	remembered[strconv.Itoa(category)] = childID
	p.SetAttribute(CombatStyleByCategoryAttribute, remembered)
}

// RememberedCombatStyleSlot returns the remembered style slot
// for a weapon category, or false when the category was never
// chosen.
func RememberedCombatStyleSlot(p *Player, category int) (int, bool) {
	if p == nil {
		return 0, false
	}
	slot, ok := readCombatStyleMemory(p)[strconv.Itoa(category)]
	return slot, ok
}

// readCombatStyleMemory reads the style-by-category map: a
// live map[string]int, or a map[string]any decoded from a save
// (JSON numbers arrive as float64; a carried save may also
// hold json.Number or int values). Anything else reads as no
// memory, as TS reads an absent or mistyped attribute as {}.
func readCombatStyleMemory(p *Player) map[string]int {
	raw := p.GetAttribute(CombatStyleByCategoryAttribute)
	switch styles := raw.(type) {
	case map[string]int:
		return styles
	case map[string]any:
		out := make(map[string]int, len(styles))
		for k, v := range styles {
			switch n := v.(type) {
			case int:
				out[k] = n
			case float64:
				out[k] = int(n)
			case json.Number:
				if i, err := n.Int64(); err == nil {
					out[k] = int(i)
				}
			}
		}
		return out
	default:
		return map[string]int{}
	}
}
